// Prefer platform overlays, which need no code: <dialog> opened with showModal() and [popover] (auto) already respond to Esc and Android Back (Chrome 120+).
// For custom overlays:
// Drop this declaration if your TypeScript lib.dom already ships CloseWatcher.
interface CloseWatcherLike extends EventTarget { destroy(): void; requestClose(): void; close(): void }
declare const CloseWatcher: (new (opts?: { signal?: AbortSignal }) => CloseWatcherLike) | undefined;

/** Registers `close` for the next close request; returns the cleanup to run when the overlay closes some other way. */
export function onCloseRequest(close: () => void): () => void {
  if (typeof CloseWatcher === 'function') {
    const w = new CloseWatcher();
    w.addEventListener('close', close);
    return () => w.destroy();
  }
  return pushOverlayEntry(close); // history fallback, next item
}

// Usage: inside the click handler that opens the drawer (user activation matters, see gotchas)
const release = onCloseRequest(() => setDrawer(false));
// ...and when the drawer is closed by its own X button or a tap on the scrim: release();

const open: Array<() => void> = [];

function depthOf(state: unknown): number {
  return typeof state === 'object' && state !== null && 'overlays' in state && typeof state.overlays === 'number' ? state.overlays : 0;
}

/** Call from the user gesture that opens the overlay. */
export function pushOverlayEntry(close: () => void): () => void {
  open.push(close);
  history.pushState({ ...(history.state ?? {}), overlays: open.length }, '');
  // Closing from the UI: let Back do it, so popstate stays the only close path.
  return () => { if (open.includes(close)) history.back(); };
}

addEventListener('popstate', (e) => {
  const depth = depthOf(e.state);
  while (open.length > depth) open.pop()?.();
});

// On boot (reload/restore), an entry may still say overlays>0 while nothing is open: neutralise it.
if (depthOf(history.state) > 0) history.replaceState({ ...history.state, overlays: 0 }, '');

type Change = 'screen' | 'refine';
export function navigate(url: string, kind: Change): void {
  if (kind === 'screen') history.pushState({ inApp: true }, '', url);
  else history.replaceState(history.state, '', url);
  render(new URL(url, location.href));
}

// Master-detail depends on layout: selecting a row is a new screen on a phone, a refinement when both panes show.
const kind: Change = matchMedia('(width >= 840px)').matches ? 'refine' : 'screen';

// Hash routers: `location.hash = x` PUSHES. To replace: history.replaceState(null, '', '#/x') (or location.replace('#/x')).

// Yurt lesson: an invite link carries a secret key in the hash. Take it into memory and out of the URL at once,
// so it never lands in (synced) browser history:
if (location.hash.includes('/k/')) { pending = location.hash; history.replaceState(null, '', buildHash(parseHash(location.hash))); }
// ...and any route change also closes transient UI (Yurt: set({ route, drawer: false })).

if ('navigation' in window) {
  navigation.addEventListener('navigate', (e) => {
    if (!e.canIntercept || e.downloadRequest !== null || e.formData) return;
    const url = new URL(e.destination.url);
    if (url.origin !== location.origin || !isAppRoute(url)) return;
    const animate = !e.hasUAVisualTransition; // Safari/Chrome already animated a swipe-back
    e.intercept({
      scroll: 'manual',
      focusReset: 'manual', // you move focus to the new screen's heading yourself
      async handler() {
        await renderRoute(url, { type: e.navigationType, animate });
        e.scroll(); // restore the remembered scroll or the #fragment, now that the content exists
      },
    });
  });
}
// Imperative API:
await navigation.navigate('#/w/abc/c/general', { history: 'replace', state: { from: 'search' } }).finished;
