// Path routing on GitHub Pages (no rewrites): ship the SPA shell as the 404 page too.
//   cp dist/index.html dist/404.html
// and serve navigations from the SW so offline/deep reloads work (Workbox):
import { NavigationRoute, registerRoute } from 'workbox-routing';
import { createHandlerBoundToURL } from 'workbox-precaching';
registerRoute(new NavigationRoute(createHandlerBoundToURL('index.html'), { denylist: [/^\/api\//] }));

// Yurt's pattern (apps/web/src/lib/route.ts)
const decode = (s: string): string => { try { return decodeURIComponent(s); } catch { return s; } };

export function parseHash(h: string): Route {
  const p = h.replace(/^#\/?/, '').split('/').map(decode);
  const r: Route = {};
  for (let i = 0; i < p.length; i += 2) {
    const val = p[i + 1];
    if (p[i] === 'w') r.code = normalizeCode(val ?? '') || undefined;
    if (p[i] === 'c' && val) r.ch = val;
    if (p[i] === 't' && val) r.thread = val; // unknown segments (e.g. an invite's /k/...) are ignored
  }
  return r;
}
// buildHash: a channel needs a workspace, a thread needs a channel, so stray parts are dropped on the way out.

// Manifest shortcuts (jump list / long-press icon) are deep links too:
// "shortcuts": [{ "name": "New message", "url": "./#/new", "icons": [{ "src": "new.png", "sizes": "96x96" }] }]

/** Mark entries the app pushed itself; history.length is useless (counts other origins and forward entries). */
export function goTo(url: string): void { history.pushState({ inApp: true }, '', url); route(); }

export function back(parentUrl: string): void {
  const s: unknown = history.state;
  const cameFromApp = typeof s === 'object' && s !== null && 'inApp' in s;
  if (cameFromApp) history.back(); // the previous screen, with its scroll and state
  else { history.replaceState(null, '', parentUrl); route(); } // deep-linked: Up to the parent
}

// Show the control where the platform gives none:
