// History API: skip your own push/pop animation when the browser already did one
addEventListener('popstate', (e) => {
  renderRoute(location.href, { animate: !e.hasUAVisualTransition });
});
// Navigation API: the same flag on NavigateEvent (see router item)

// Custom swipe-to-close on a full-screen panel (Yurt: ui/Panels.tsx + lib/gestures.ts):
// - lock axis after ~10px; a mostly-vertical drag is a scroll, never a swipe
// - complete at ~64px, or ~32px if it's a flick (>= 0.5 px/ms)
// - translate the panel with the finger, haptic tick when the threshold is reached
// - ignore touches that start in the system edge zone so two backs can't fire:
const SYSTEM_EDGE_PX = 24;
function startsInSystemEdge(e: PointerEvent): boolean {
  const rtl = getComputedStyle(document.documentElement).direction === 'rtl';
  return rtl ? e.clientX > innerWidth - SYSTEM_EDGE_PX : e.clientX < SYSTEM_EDGE_PX;
}
// .panel { touch-action: pan-y; } lets vertical scrolling stay native while you own horizontal drags

history.scrollRestoration = 'manual'; // the browser restores before async content exists, and never restores inner scrollers
const saved = new Map<string, number>();
export function leaveScreen(key: string, scroller: HTMLElement): void { saved.set(key, scroller.scrollTop); }
export function enterScreen(key: string, scroller: HTMLElement, backForward: boolean): void {
  requestAnimationFrame(() => { scroller.scrollTop = backForward ? (saved.get(key) ?? 0) : 0; });
}
// Survive reloads: mirror `saved` into sessionStorage on pagehide.

// Resume where the user left off
const LAST = 'last-route';
addEventListener('pagehide', () => { try { localStorage.setItem(LAST, location.hash); } catch { /* storage blocked */ } });
if (location.hash === '' || location.hash === '#/') {
  try { const r = localStorage.getItem(LAST); if (r && isKnownRoute(r)) history.replaceState(null, '', r); } catch { /* ignore */ }
}
