// app
interface LaunchParams { readonly targetURL?: string }
declare global { interface Window { launchQueue?: { setConsumer(cb: (p: LaunchParams) => void): void } } }
window.launchQueue?.setConsumer((p) => {
  if (p.targetURL) routeTo(new URL(p.targetURL)); // focus-existing does NOT navigate for you
});

// Notifications (all platforms incl. iOS 16.4+): focus the existing client from the service worker
self.addEventListener('notificationclick', (e) => {
  e.waitUntil((async () => {
    const all = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const c = all[0];
    if (c) { await c.focus(); c.postMessage({ type: 'open', url: e.notification.data.url }); }
    else await self.clients.openWindow(e.notification.data.url);
  })());
});

const bc = new BroadcastChannel('app');
navigator.locks.request('leader', async () => {
  startLiveSync((update) => { apply(update); bc.postMessage(update); });
  await new Promise<never>(() => {}); // hold the lock until this window closes
});
bc.onmessage = (e: MessageEvent<unknown>) => { if (isUpdate(e.data)) apply(e.data); };

// Presence (Yurt: online/away from page visibility)
const presence = (): 'active' | 'visible' | 'away' =>
